import java.util.*;

class Solution {
  public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
      int u = edge[0] - 1, v = edge[1] - 1;
      graph[u].add(v);
      graph[v].add(u);
    }
    int[][] distance = new int[n][n];
    for (int[] row : distance) Arrays.fill(row, -1);
    for (int start = 0; start < n; start++) {
      ArrayDeque<Integer> queue = new ArrayDeque<>();
      queue.add(start);
      distance[start][start] = 0;
      while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : graph[u])
          if (distance[start][v] == -1) {
            distance[start][v] = distance[start][u] + 1;
            queue.add(v);
          }
      }
    }
    int[] answer = new int[n - 1];
    for (int mask = 1; mask < (1 << n); mask++) {
      int first = Integer.numberOfTrailingZeros(mask), count = Integer.bitCount(mask);
      int seen = 0;
      ArrayDeque<Integer> queue = new ArrayDeque<>();
      queue.add(first);
      seen |= 1 << first;
      while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : graph[u])
          if ((mask & (1 << v)) != 0 && (seen & (1 << v)) == 0) {
            seen |= 1 << v;
            queue.add(v);
          }
      }
      if (Integer.bitCount(seen) != count) continue;
      int diameter = 0;
      for (int u = 0; u < n; u++)
        if ((mask & (1 << u)) != 0)
          for (int v = u + 1; v < n; v++)
            if ((mask & (1 << v)) != 0) diameter = Math.max(diameter, distance[u][v]);
      if (diameter > 0) answer[diameter - 1]++;
    }
    return answer;
  }
}
